(async () => {
  for (const index in urls) {
    console.log(urls[index].nameTw);
    if (pageContents[index] && pageContents[index].tw) {
      handleItems(pageContents[index].tw, "tw");
    } else {
      let request = new Request(urls[index].tw);
      await fetch(request).then((response) =>
        handleUrl(response, index, handleItems)
      );
    }

    if (pageContents[index] && pageContents[index].us) {
      handleItems(pageContents[index].us, "us");
    } else {
      let request = new Request(urls[index].us);
      await fetch(request).then((response) =>
        handleUrl(response, index, handleItems)
      );
    }

    // console.log(`"Rare ${urls[index].nameUs}" => "稀有${urls[index].nameTw}"`);
  }

  // 這邊拿到的資料存成 items.json
  console.log(JSON.stringify(data));
})();

function handleUrl(response, index, handle) {
  if (!response.ok) {
    return Promise.resolve();
  }

  if (response.url.indexOf("https://poedb.tw/tw/") !== -1) {
    return response.text().then((str) => {
      pageContents[index] = {
        ...pageContents[index],
        tw: str,
      };
      handle(str, "tw");
    });
  }
  if (response.url.indexOf("https://poedb.tw/us/") !== -1) {
    return response.text().then((str) => {
      pageContents[index] = {
        ...pageContents[index],
        us: str,
      };
      handle(str, "us");
    });
  }
}

function handleItems(str, lang) {
  let responseDoc = new DOMParser().parseFromString(str, "text/html");
  responseDoc.querySelectorAll("#Contacts,#Blueprints").forEach((ele) => {
    ele.remove();
  });
  responseDoc
    .querySelectorAll(
      "a.whiteitem,a.item_unique,a.uniqueitem,a.item_currency,a.itemclass_map,a.divination,a.gem_red,a.gem_green,a.gem_blue,a.gemitem"
    )
    .forEach((ele) => {
      const href = ele.href;
      const key = href.replace(`https://poedb.tw/${lang}/`, "");
      const name = ele.innerText;
      let base = null;

      // 如果是傳奇的話，如果傳奇名稱+基底有包含傳奇名稱，把傳奇名稱取代掉把基底抓出來
      if (
        ele.classList.contains("item_unique") ||
        ele.classList.contains("uniqueitem")
      ) {
        const legend = Object.values(uniqueItems).find((i) => {
          if (lang == "tw") {
            // 如果全名有贗品，但關鍵字沒有贗品，則不是該搜尋對象，回傳 false
            if (
              name.indexOf("贗品") !== -1 &&
              i.nameZh.indexOf("贗品") === -1
            ) {
              return false;
            }
            return name.indexOf(i.nameZh) !== -1;
          }

          if (lang == "us") {
            // 如果全名有 Replica，但關鍵字沒有Replica，則不是該搜尋對象，回傳 false
            if (
              name.indexOf("Replica") !== -1 &&
              i.nameEn.indexOf("Replica") === -1
            ) {
              return false;
            }
            return name.indexOf(i.nameEn) !== -1;
          }

          return false;
        });

        if (legend) {
          const replace = lang == "tw" ? legend.nameZh : legend.nameEn;
          base = name.replace(replace, "").trim();
        }
      }

      if (lang == "tw" && name == "Orb of Alchemy") {
        console.log(str);
      }

      data[key] = data[key] ?? {};
      if (base) {
        data[key][lang] = {
          name: name.replace(base, "").trim(),
          url: href,
          base: base,
          fullname: name,
        };
      } else {
        data[key][lang] = {
          name: name,
          url: href,
        };
      }
    });
}
